import cpmpy as cp
import json

# Word list sorted by descending length then alphabetically:
# Indices 0..4: length 5: HOSES, LASER, SAILS, SHEET, STEER
# Indices 5..9: length 4: HEEL, HIKE, KEEL, KNOT, LINE
# Indices 10..14: length 3: AFT, ALE, EEL, LEE, TIE
word_list = [
    "HOSES", "LASER", "SAILS", "SHEET", "STEER",
    "HEEL", "HIKE", "KEEL", "KNOT", "LINE",
    "AFT", "ALE", "EEL", "LEE", "TIE"
]

# Precompute letter codes, pad to length 5 with -1
max_len = 5
num_words = len(word_list)
# arr_letters[k] will be the list of the k-th letter code for each word
arr_letters = []
for k in range(max_len):
    col = []
    for w in word_list:
        if k < len(w):
            col.append(ord(w[k]) - ord('A'))
        else:
            col.append(-1)
    arr_letters.append(col)

# Slot definitions: slot number -> list of (row, col) positions
slots = {
    1: [(1,1),(1,2),(1,3),(1,4),(1,5)],      # across length 5
    2: [(1,3),(2,3),(3,3),(4,3),(5,3)],      # down   length 5
    3: [(1,5),(2,5),(3,5),(4,5),(5,5)],      # down   length 5
    4: [(3,2),(3,3),(3,4),(3,5)],            # across length 4
    5: [(3,4),(4,4),(5,4),(6,4)],            # down   length 4
    6: [(4,1),(5,1),(6,1)],                  # down   length 3
    7: [(4,3),(4,4),(4,5)],                  # across length 3
    8: [(5,1),(5,2),(5,3),(5,4),(5,5)]       # across length 5
}

# Map lengths to possible word indices
length_to_indices = {}
for idx, w in enumerate(word_list):
    length_to_indices.setdefault(len(w), []).append(idx)

# Model
model = cp.Model()

# Decision variables: w[i] is the index of the chosen word for slot i
w = {}
for i, positions in slots.items():
    L = len(positions)
    # domain: word indices with matching length
    dom = length_to_indices[L]
    w[i] = cp.intvar(dom, name=f"w{i}")

# All chosen words must be different
model += cp.AllDifferent([w[i] for i in slots])

# Letter variables via Element: letter_vars[i][k] is the k-th letter code of slot i
letter_vars = {i: [] for i in slots}
for i, positions in slots.items():
    L = len(positions)
    for k in range(L):
        # arr_letters[k] maps word-index to letter code at position k
        lv = cp.Element(arr_letters[k], w[i])
        letter_vars[i].append(lv)

# Intersection constraints: same grid cell => same letter
# Build a map from grid cell to list of (slot, index_in_slot)
cell_map = {}
for i, positions in slots.items():
    for k, cell in enumerate(positions):
        cell_map.setdefault(cell, []).append((i, k))

for cell, occs in cell_map.items():
    # if more than one slot covers this cell, enforce equality
    if len(occs) > 1:
        # pairwise equalities
        for (i1, k1) in occs:
            for (i2, k2) in occs:
                if (i1, k1) < (i2, k2):
                    model += (letter_vars[i1][k1] == letter_vars[i2][k2])

# Solve and print
if model.solve():
    solution = {'E': [int(w[i].value()) for i in sorted(slots)]}
    print(json.dumps(solution, indent=4))
else:
    print("No solution found.")
